"""RoboPaint execution record. Uses only public robot observations and actions."""
import os, sys, json, time, traceback
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
r=Robot()
spec=r.spec()
ROOT='/app/output'
quat=np.array([0.,1.,0.,0.])
obs=r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True)
obs.save(ROOT+'/calibration')
lastpose=np.array(obs.meta['proprio']['now'][7:14])
seq=0

def submit(P,note='',cameras=['practice_cam'],video='none',fps=4):
 global lastpose,seq
 P=np.asarray(P,float)
 for k in range(0,len(P),180):
  chunk=P[k:k+180]
  before=r.status()
  seq+=1
  np.save(f'{ROOT}/actions_{seq:04d}.npy',chunk)
  try:
   res=r.submit('ee_pose',chunk,dt=.05,cameras=cameras,video=video,video_fps=fps,note=note)
  except Exception:
   s=r.wait_ready()
   if s['control_steps']==before['control_steps']:
    res=r.submit('ee_pose',chunk,dt=.05,cameras=cameras,video=video,video_fps=fps,note=note)
   else:
    raise RuntimeError('Call outcome needs inspection: '+str(s))
  res.save(f'{ROOT}/runs/{seq:04d}')
  lastpose=np.array(res.meta['proprio']['now'][7:14])
  with open(ROOT+'/execution.jsonl','a') as f: f.write(json.dumps({'seq':seq,'note':note,'meta':res.meta})+'\n')
  print('CALL',seq,'pose',lastpose[:3].round(5),'plan',res.meta.get('plan'),'left',res.meta.get('time_left_s'),flush=True)
  if res.stopped: raise RuntimeError('Partial execution')
 return res

def trajectory(points,speed=.06,hold=.25):
 # Points are world x,y,z; interpolate continuous safe targets.
 out=[]; prev=lastpose[:3].copy()
 for p in points:
  p=np.asarray(p,float); n=max(1,int(np.ceil(np.linalg.norm(p-prev)/(speed*.05))))
  for t in np.linspace(0,1,n+1)[1:]: out.append(np.r_[prev*(1-t)+p*t,quat])
  prev=p
 for _ in range(round(hold/.05)): out.append(np.r_[prev,quat])
 return np.asarray(out)

def move(points,speed=.06,hold=.25,**kwargs): return submit(trajectory(points,speed,hold),**kwargs)

print('READY',r.status(),flush=True)
# Each received local task is preserved, and can be replayed by this script.
if __name__=='__main__':
 for line in sys.stdin:
  try:
   task=line.strip()
   if not task: continue
   if task=='quit': break
   with open(ROOT+'/tasks_executed.txt','a') as f: f.write(task+'\n')
   exec(compile(open(task).read(),task,'exec'),globals())
   print('TASK_DONE',task,flush=True)
  except Exception: traceback.print_exc()
